.pi, np.pi)) # VA\\n\\n    # Pg and Qg\\n    for i in range(num_gens):\\n        x0[2*num_buses + i] = gens[i][1] / baseMVA # PG\\n        x0[2*num_buses + num_gens + i] = gens[i][2] / baseMVA # QG\\n        bounds.append((gens[i][9] / baseMVA, gens[i][8] / baseMVA)) # PMIN, PMAX\\n        bounds.append((gens[i][4] / baseMVA, gens[i][3] / baseMVA)) # QMIN, QMAX\\n\\n    # Reference bus constraint\\n    ref_buses = [i for i, b in enumerate(buses) if b[1] == 3]\\n    \\n    def objective(x):\\n        total_cost = 0\\n        for i in range(num_gens):\\n            pg = x[2*num_buses + i] * baseMVA\\n            cost_coeffs = gencosts[i][4:]\\n            # Assuming polynomial cost: c2*Pg^2 + c1*Pg + c0\\n            if gencosts[i][3] == 3:\\n                total_cost += cost_coeffs[0] * pg**2 + cost_coeffs[1] * pg + cost_coeffs[2]\\n            elif gencosts[i][3] == 2:\\n                total_cost += cost_coeffs[0] * pg + cost_coeffs[1]\\n        return total_cost\\n\\n    def constraints(x):\\n        Vm = x[:num_buses]\\n        Va = x[num_buses:2*num_buses]\\n        Pg = x[2*num_buses:2*num_buses + num_gens]\\n        Qg = x[2*num_buses + num_gens:]\\n\\n        V = Vm * np.exp(1j * Va)\\n        \\n        # Power balance\\n        P_gen = np.zeros(num_buses)\\n        Q_gen = np.zeros(num_buses)\\n        for i in range(num_gens):\\n            bus_idx = bus_idx_map[int(gens[i][0])]\\n            P_gen[bus_idx] += Pg[i]\\n            Q_gen[bus_idx] += Qg[i]\\n\\n        P_load = np.array([b[2] for b in buses]) / baseMVA\\n        Q_load = np.array([b[3] for b in buses]) / baseMVA\\n        Gs = np.array([b[4] for b in buses]) / baseMVA\\n        Bs = np.array([b[5] for b in buses]) / baseMVA\\n\\n        # Ybus construction (simplified for constraints)\\n        # But it's better to compute P_inj and Q_inj directly\\n        \\n        res = []\\n        \\n        # Reference bus angle\\n        for rb in ref_buses:\\n            res.append(Va[rb])\\n\\n        # Branch flows and power balance\\n        P_inj = np.zeros(num_buses)\\n        Q_inj = np.zeros(num_buses)\\n        \\n        # Bus shunt injections\\n        P_inj -= Gs * Vm**2\\n        Q_inj += Bs * Vm**2\\n\\n        branch_flows_from = []\\n        branch_flows_to = []\\n\\n        for br in branches:\\n            f_idx = bus_idx_map[int(br[0])]\\n            t_idx = bus_idx_map[int(br[1])]\\n            r = br[2]\\n            x_br = br[3]\\n            b_br = br[4]\\n            tap = br[8] if br[8] != 0 else 1.0\\n            shift = np.radians(br[9])\\n            \\n            Y = 1.0 / (r + 1j * x_br)\\n            T = tap * np.exp(1j * shift)\\n            \\n            # From side\\n            S_from = (Y + 1j * b_br / 2).conjugate() * (np.abs(V[f_idx])**2 / np.abs(T)**2) - Y.conjugate() * (V[f_idx] * V[t_idx].conjugate() / T)\\n            # To side\\n            S_to = (Y + 1j * b_br / 2).conjugate() * (np.abs(V[t_idx])**2) - Y.conjugate() * (V[f_idx].conjugate() * V[t_idx] / T.conjugate())\\n            \\n            P_inj[f_idx] -= S_from.real\\n            Q_inj[f_idx] -= S_from.imag\\n            P_inj[t_idx] -= S_to.real\\n            Q_inj[t_idx] -= S_to.imag\\n            \\n            branch_flows_from.append(np.abs(S_from))\\n            branch_flows_to.append(np.abs(S_to))\\n\\n        for i in range(num_buses):\\n            res.append(P_gen[i] - P_load[i] + P_inj[i])\\n            res.append(Q_gen[i] - Q_load[i] + Q_inj[i])\\n\\n        # Branch flow limits\\n        for i, br in enumerate(branches):\\n            limit = br[5] / baseMVA\\n            if limit \u003e 0:\\n                res.append(limit - branch_flows_from[i])\\n                res.append(limit - branch_flows_to[i])\\n        \\n        return np.array(res)\\n\\n    # For minimize, we need separate eq and ineq constraints\\n    def eq_constraints(x):\\n        Vm = x[:num_buses]\\n        Va = x[num_buses:2*num_buses]\\n        Pg = x[2*num_buses:2*num_buse